import {generateAsset,assetToSvg} from './art-kit.js';
import {MATERIALS} from './materials.js';
import {P,BIOME_ART} from './palette.js';
import {redeemZagGear,ZAG_ROUTES,ZAG_SIGILS,ZAG_MODULES,upgradeZagModule,adjustZagDie,planZagTurn,autoZagStep,ZAG_WHEEL,ZAG_BIOMES,ZAG_MINING_GOAL,ZAG_STEP_MS,ZAG_TOOLS,spinZag,dealZag,moveZag,chooseZagRoute,zagDestination,craftZagTool,useZagTool,investZag,withdrawZag,bankZag,settleZag,zagRoundState,zagTile,zagBoardTile} from './zag.js';
const routeName=r=>({safe:'SEGURA',craft:'OFICINA',greed:'OUSADA'})[r];
const routeColor=r=>({safe:P.cyan,craft:P.lemon,greed:P.pink})[r];
const fmt=n=>Math.floor(n).toLocaleString('pt-BR');
const art=(type,variant=0)=>assetToSvg(generateAsset(type,{variant}));
const sum=a=>a.reduce((x,y)=>x+y,0);
export function zagDie(n=3){const spots={1:[[25,25]],2:[[14,14],[36,36]],3:[[14,14],[25,25],[36,36]],4:[[14,14],[36,14],[14,36],[36,36]],5:[[14,14],[36,14],[25,25],[14,36],[36,36]],6:[[14,12],[36,12],[14,25],[36,25],[14,38],[36,38]]};return '<svg viewBox="0 0 50 50" aria-hidden="true"><rect x="2" y="2" width="46" height="46" rx="10" fill="'+P.lemon+'" stroke="'+P.ink+'" stroke-width="3"/>'+spots[n].map(([x,y])=>'<circle cx="'+x+'" cy="'+y+'" r="4" fill="'+P.ink+'"/>').join('')+'</svg>';}
function symbol(type,kind=0){if(type==='rune')return '<svg viewBox="0 0 50 50" aria-hidden="true"><path d="m25 2 21 22-21 24L4 24Z" fill="'+P.pink+'" stroke="'+P.ink+'" stroke-width="3"/><text x="25" y="32" text-anchor="middle" fill="'+P.white+'" font-size="26">'+['☀','☽','❧'][kind]+'</text></svg>';if(type==='parts')return art('rock',1);if(type==='crystal')return art('crystal',kind);if(type==='cache'||type==='camp')return art('crate');if(type==='audit')return art('zag',2);if(type==='xp')return art('crystal',3);if(type==='trap')return art('rock',2);if(type==='dice')return zagDie(3);if(type==='start')return art('lantern');return '<svg viewBox="0 0 50 50" aria-hidden="true">'+(type==='guard'?'<path d="M25 3 44 12 39 33 25 47 11 33 6 12Z" fill="'+P.cyan+'" stroke="'+P.ink+'" stroke-width="3"/><path d="m15 24 7 7 14-15" fill="none" stroke="'+P.ink+'" stroke-width="4"/>':'<path d="m25 2 7 14 16 3-12 12 3 16-14-8-14 8 3-16L2 19l16-3Z" fill="'+P.lemon+'" stroke="'+P.ink+'" stroke-width="3"/><text x="25" y="31" text-anchor="middle" font-size="18" font-weight="900" fill="'+P.ink+'">×2</text>')+'</svg>';}
function placed(svg,x,y,w,h=w){return svg.replace('<svg ','<svg x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" ');}
const color=t=>['trap','audit'].includes(t.type)?P.pink:t.type==='crystal'?MATERIALS[t.kind].color:t.type==='guard'?P.cyan:P.lemon;
export function boardPoint(position,base,route='safe'){return{x:position%12===0?300:route==='safe'?105:route==='craft'?300:495,y:105+(position-base)*108};}
export function zagBoardBase(position){return Math.max(0,position-3);}
function boardMarkup(s,base=s.zag.position){
 const z=s.zag,end=base+14,point=boardPoint(z.position,base,z.lastRoute),biome=zagTile(s.seed,z.position).biome,colors=BIOME_ART[biome],height=105+14*108+95;
 const tiles=[];
 for(let n=base;n<=end;n++)for(const route of n%12===0?['safe']:ZAG_ROUTES)tiles.push({n,route,...boardPoint(n,base,route),...zagBoardTile(s,n,route)});
 let paths='';for(let n=base;n<end;n++)for(const route of ZAG_ROUTES){const a=boardPoint(n,base,route),b=boardPoint(n+1,base,route);paths+='<path d="M'+a.x+' '+a.y+' L'+b.x+' '+b.y+'" fill="none" stroke="'+routeColor(route)+'" stroke-width="8" stroke-dasharray="8 7" opacity=".65"/>';}
 return '<div class="zag-board-head"><span>CAMADA '+fmt(Math.floor(z.position/12)+1)+' · '+ZAG_BIOMES[biome]+'</span><b id="zagPosition">CASA '+fmt(z.position)+'</b></div><div class="zag-lane-labels"><b>SEGURA</b><b>OFICINA</b><b>OUSADA</b></div><div class="zag-board-window" tabindex="0" aria-label="Explore as próximas casas rolando o tabuleiro"><svg class="zag-board" viewBox="0 0 600 '+height+'" role="img" aria-label="Três rotas de caverna. Casa atual '+z.position+'."><defs><pattern id="zagStone" width="160" height="140" patternUnits="userSpaceOnUse"><path d="m12 25 12-9 32 4 13 22-48 6Z M98 103l15-18 28 5 7 22-43 7Z" fill="'+colors.floor+'"/></pattern></defs><rect width="600" height="'+height+'" fill="'+colors.edge+'"/><rect width="600" height="'+height+'" fill="url(#zagStone)"/><g id="zagBoardWorld" data-base="'+base+'">'+paths+
 tiles.map(t=>'<g class="zag-tile" data-position="'+t.n+'" data-route="'+t.route+'"><title>Casa '+t.n+': '+t.name+'</title><rect x="'+(t.x-91)+'" y="'+(t.y-25)+'" width="182" height="69" rx="15" fill="'+P.black+'"/><rect x="'+(t.x-91)+'" y="'+(t.y-32)+'" width="182" height="69" rx="15" fill="'+BIOME_ART[t.biome].floor+'" stroke="'+color(t)+'" stroke-width="2"/>'+placed(symbol(t.type,t.type==='rune'?t.sigil:t.kind),t.x-80,t.y-33,47,50)+'<text x="'+(t.x+20)+'" y="'+(t.y-8)+'" text-anchor="middle" fill="'+color(t)+'" font-size="14" font-weight="900">'+t.name+'</text><text x="'+(t.x+20)+'" y="'+(t.y+17)+'" text-anchor="middle" fill="'+P.white+'" font-size="14" font-weight="800">'+tileHint(t,z)+'</text><text x="'+(t.x-87)+'" y="'+(t.y+29)+'" fill="'+P.silver+'" font-size="12">'+fmt(t.n)+'</text></g>').join('')+
 '<g id="zagPawn" transform="translate('+point.x+','+point.y+')"><ellipse cy="-36" rx="22" ry="7" fill="'+P.ink+'"/><g id="zagPawnHop">'+placed(art('miner'),-33,-101,66,73)+'</g></g></g></svg></div>';
}
function tileHint(t,z){
 const amount=Math.floor(t.amount*(1+(z?.modules.treasure||0)*.1)*(z?.luck?2:1)),defense=1-(z?.modules.protection||0)*.2,loss=n=>z?.guard?'ESCUDO COBRE':'−'+Math.round(n*defense)+'%';
 return t.type==='parts'?'+1 fragmento':t.type==='rune'?'Selo · '+loss(10)+(z?.guard?'':' mochila'):t.type==='crystal'?'+'+amount+' '+MATERIALS[t.kind].name:t.type==='cache'?'+'+amount*4+' cristais':t.type==='xp'?'+'+t.amount+' XP':t.type==='trap'?loss(25)+' mochila':t.type==='audit'?loss(10)+' investimento':t.type==='camp'?'Guardar · render 5%':t.type==='guard'?'Bloqueia 1 perigo':t.type==='luck'?'Próximo saque ×2':t.type==='dice'?(z?.bonusDice?'+1 dado':'+1 fragmento'):'Você está aqui';
}
function wheelMarkup(){return '<div class="zag-wheel-wrap"><i class="zag-pointer" aria-hidden="true"></i><svg id="zagWheel" viewBox="0 0 300 300" aria-label="Roleta de dados e cristais">'+ZAG_WHEEL.map((p,i)=>{const a=(-90+i*45)*Math.PI/180,b=a+Math.PI/4,mid=a+Math.PI/8;return '<path d="M150 150 L'+(150+140*Math.cos(a))+' '+(150+140*Math.sin(a))+' A140 140 0 0 1 '+(150+140*Math.cos(b))+' '+(150+140*Math.sin(b))+' Z" fill="'+[P.deepBlue,P.plum,P.forest,P.plum,P.wood,P.plum,P.deepBlue,P.plum][i]+'" stroke="'+P.ink+'" stroke-width="3"/><g transform="translate('+(150+96*Math.cos(mid))+','+(150+96*Math.sin(mid))+') rotate('+(i*45+22.5)+')">'+placed(zagDie(p.dice),-18,-22,36,36)+'<text y="29" text-anchor="middle" font-size="15" fill="'+(p.amount?MATERIALS[p.kind].color:P.white)+'" font-weight="900">'+p.dice+(p.amount?' + ◆':' D')+'</text></g>';}).join('')+'<circle cx="150" cy="150" r="35" fill="'+P.ink+'" stroke="'+P.lemon+'" stroke-width="4"/><text x="150" y="159" text-anchor="middle" font-size="22" fill="'+P.lemon+'" font-weight="900">ZAG</text><circle cx="150" cy="150" r="143" fill="none" stroke="'+P.gold+'" stroke-width="6"/></svg></div>';}
function resultText(r){if(!r)return {title:'ESCOLHA SEU CAMINHO',detail:''};const total=sum(r.gained),lost=sum(r.lost),banked=sum(r.banked),fee=sum(r.fee||[]);const title={spin:'+'+r.dice+' DADOS',crystal:'+'+total+' CRISTAIS',cache:'TESOURO! +'+total,trap:r.blocked?'ESCUDO SALVOU!':lost?'−'+lost+' CRISTAIS':'MOCHILA A SALVO',audit:r.blocked?'ESCUDO SALVOU!':fee?'AUDITORIA · −'+fee:'COFRE A SALVO',xp:'+'+r.xp+' XP',dice:r.dice?'+1 DADO':'+1 FRAGMENTO',parts:'+1 FRAGMENTO',rune:r.collection?'COLEÇÃO! +1 ENGRENAGEM':r.parts?'SELO REPETIDO · +2 FRAGMENTOS':'SELO '+ZAG_SIGILS[r.sigil],guard:'ESCUDO PRONTO',luck:'PRÓXIMO SAQUE ×2',camp:'COFRE ENCONTRADO',bank:'SAQUE GUARDADO'}[r.type];return {title,detail:banked?'+'+fmt(banked)+' na vila'+(sum(r.interest||[])?' · +'+sum(r.interest)+' de juros':''):r.type==='guard'?'BLOQUEIA 1 PERIGO':r.type==='luck'?'PRÓXIMO SAQUE ×2':r.type==='xp'?'XP PARA A TEIA':r.type==='spin'&&total?'+'+total+' cristais na mochila.':''};}
export function zagRewardDisplay(r){
 if(!r)return {tone:'idle',tokens:[],hero:''};
 const tokens=[];
 const mineral=(values,sign,kind)=>values.forEach((n,i)=>{if(n>0)tokens.push({icon:art('crystal',i),text:sign+fmt(n),label:MATERIALS[i].name,color:MATERIALS[i].color,kind});});
 if(r.type!=='camp')mineral(r.gained||[],'+','gain');mineral(r.banked||[],'+','bank');mineral(r.lost||[],'−','loss');mineral(r.fee||[],'−','loss');
 if(r.dice>0)tokens.push({icon:zagDie(),text:'+'+r.dice,label:r.dice===1?'DADO':'DADOS',color:P.lemon,kind:'gain'});
 if(r.xp>0)tokens.push({icon:symbol('xp'),text:'+'+fmt(r.xp),label:'XP',color:P.cyan,kind:'gain'});
 if(r.parts>0)tokens.push({icon:symbol('parts'),text:'+'+r.parts,label:r.parts===1?'FRAGMENTO':'FRAGMENTOS',color:P.sand,kind:'gain'});
 if(r.collection)tokens.push({icon:symbol('rune',r.sigil),text:'+1',label:'ENGRENAGEM',color:P.gold,kind:'gain'});
 if(r.type==='guard'&&r.blocked!==true)tokens.push({icon:symbol('guard'),text:'+1',label:'ESCUDO',color:P.cyan,kind:'gain'});
 if(r.type==='luck')tokens.push({icon:symbol('luck'),text:'×2',label:'PRÓXIMO SAQUE',color:P.lemon,kind:'gain'});
 if(r.blocked)tokens.push({icon:symbol('guard'),text:'SALVO',label:'ESCUDO',color:P.cyan,kind:'gain'});
 if(r.type==='rune'&&!r.collection&&!r.parts)tokens.push({icon:symbol('rune',r.sigil),text:'+1',label:'SELO',color:P.pink,kind:'gain'});
 const loss=!!sum(r.lost||[])||!!sum(r.fee||[]),tone=loss?'loss':r.type==='cache'||r.collection?'jackpot':r.type==='bank'||sum(r.banked||[])?'bank':'gain';
 const hero=loss?'−'+fmt(sum(r.lost||[])+sum(r.fee||[]))+' CRISTAIS':r.blocked?'ESCUDO SALVOU':sum(r.banked||[])>0?'+'+fmt(sum(r.banked))+' GUARDADOS':sum(r.gained||[])>0?'+'+fmt(sum(r.gained))+' CRISTAIS':resultText(r).title;
 return {tone,tokens,hero};
}
export function zagMarkup(s,selected=0,automatic=false,boardHtml=null,boardBase=s.zag.position){
 const z=s.zag,busy=!!z.active,feedback=resultText(z.result),dest=z.active?.type==='move'?{steps:z.active.steps,position:z.position+z.active.steps,...zagBoardTile(s,z.position+z.active.steps,z.active.route)}:zagDestination(s,selected);
 return '<section class="zag-game" id="zagGame" data-auto="'+automatic+'" data-phase="'+(z.active?.type||'idle')+'"><header class="zag-heading"><div class="zag-host">'+art('zag')+'</div><div><span>ZAG</span><h2>TRILHA DA FORTUNA</h2></div><div class="zag-wallet"><span>'+art('ticket')+'<b>'+fmt(z.passes)+'</b> PASSES</span><span>'+zagDie()+'<b>'+fmt(z.dice)+'</b> RESERVA</span></div></header><div class="zag-layout"><div class="zag-map">'+collectionMarkup(s)+(boardHtml??boardMarkup(s,boardBase))+'<div class="zag-feedback" role="status" aria-live="polite"><strong id="zagHeadline">'+feedback.title+'</strong><span id="zagDetail">'+feedback.detail+'</span></div></div><aside class="zag-controls"><button id="zagAuto" aria-pressed="'+automatic+'" class="zag-auto">'+(automatic?'PARAR AFK':'JOGAR AFK')+'<small>'+(automatic?'ESCOLHA AUTOMÁTICA':'USA DADOS E PASSES')+'</small></button><div class="zag-roulette-row">'+wheelMarkup()+'<div><button id="zagSpin" class="secondary" '+(busy||!z.passes?'disabled':'')+'>GIRAR ROLETA<small>1 passe → dados</small></button><span class="zag-pass-note">'+z.mined+'/'+ZAG_MINING_GOAL+' cristais no Abismo</span></div></div><div class="zag-routes">'+ZAG_ROUTES.map(route=>'<button data-route="'+route+'" aria-pressed="'+(z.route===route)+'" '+(busy?'disabled':'')+'>'+ routeName(route)+'<small>'+({safe:'Cristais · proteção',craft:'Ferramentas · sorte',greed:'Selos · tesouros ×3'})[route]+'</small>'+'</button>').join('')+'</div><div class="zag-hand">'+(z.hand.length?z.hand.map((n,i)=>{const d=zagDestination(s,i);return '<button data-die="'+i+'" aria-pressed="'+(selected===i)+'" '+(busy?'disabled':'')+' aria-label="Dado '+n+', casa '+d.position+', '+d.name+', '+tileHint(d,z)+'">'+zagDie(n)+'<strong>'+d.name+'</strong><small>'+tileHint(d,z)+'</small></button>';}).join(''):'<button id="zagDeal" class="primary" '+(busy||!z.dice?'disabled':'')+'>ROLAR ATÉ 3 DADOS</button>')+'</div><div class="zag-move-preview">'+(dest?'CASA '+dest.position+' · '+dest.name:'ESCOLHA UM DADO')+(z.jump?' · SALTO +2':'')+'</div><button id="zagMove" class="primary" '+(busy||!dest?'disabled':'')+'>AVANÇAR '+(dest?dest.steps+' CASAS':'')+'</button>'+(z.modules.precision?'<div class="zag-adjust"><button data-adjust="-1" '+(busy||!dest||!z.adjustments||z.hand[selected]<=1?'disabled':'')+'>DADO −1</button><b>'+z.adjustments+' AJUSTES</b><button data-adjust="1" '+(busy||!dest||!z.adjustments||z.hand[selected]>=6?'disabled':'')+'>DADO +1</button></div>':'')+'<div class="zag-tools">'+Object.entries(ZAG_TOOLS).map(([id,t])=>'<button data-tool="'+id+'" title="'+t.hint+'" '+(busy||!dest||!z.tools[id]?'disabled':'')+'>'+t.name+' <b>'+z.tools[id]+'</b></button>').join('')+'</div><div class="zag-buffs">'+(z.guard?symbol('guard')+'<b>PROTEGIDO</b>':'')+(z.luck?symbol('luck')+'<b>'+z.luck+' SAQUES</b>':'')+'</div><div class="zag-satchel"><h3>MOCHILA</h3><div>'+z.satchel.map((n,i)=>'<span style="--mineral:'+MATERIALS[i].color+'" title="'+MATERIALS[i].name+'">'+art('crystal',i)+'<b>'+fmt(n)+'</b></span>').join('')+'</div><button id="zagBank" class="secondary" '+(busy||!sum(z.satchel)?'disabled':'')+'>GUARDAR NA VILA</button></div></aside></div>'+
 '<div class="zag-workshops"><details><summary>ENGRENAGENS · '+z.gears+'</summary><p>Sol + Lua + Raiz = 1 engrenagem. Só melhora o tabuleiro.</p><div class="zag-craft">'+Object.entries(ZAG_MODULES).map(([id,m])=>'<div><strong>'+m.name+' · '+z.modules[id]+'/3</strong><span>'+m.hint+'</span><button data-module="'+id+'" '+(busy||!z.gears||z.modules[id]>=3?'disabled':'')+'>'+(z.modules[id]>=3?'MÁXIMO':'MELHORAR · 1 ⚙')+'</button></div>').join('')+'</div><button id="zagKit" '+(busy||!z.gears?'disabled':'')+'>3 FERRAMENTAS · 1 ⚙</button></details><details><summary>FERRAMENTAS · '+z.fragments+' FRAGMENTOS</summary><p>3 fragmentos = 1 carga. Cada passe minerado traz 1 fragmento.</p><div class="zag-craft">'+Object.entries(ZAG_TOOLS).map(([id,t])=>'<div><strong>'+t.name+'</strong><span>'+t.hint+'</span><button data-craft="'+id+'" '+(busy||z.fragments<3?'disabled':'')+'>CRIAR · 3 ◆</button></div>').join('')+'</div></details><details><summary>COFRE · '+fmt(sum(z.investment))+' CRISTAIS</summary><p>+5% a cada 12 casas atravessadas. Deposite ao parar num cofre. Saque quando quiser. Auditoria: −10%. Limite: 10.000 por cor.</p><div class="zag-invest">'+MATERIALS.map((m,i)=>'<div style="--mineral:'+m.color+'">'+art('crystal',i)+'<strong>'+m.name+' · '+z.investment[i]+'</strong>'+[25,100,250].map(amount=>'<button data-invest="'+i+':'+amount+'" '+(busy||!z.position||z.position%12!==0||s.materials[i]<amount||z.investment[i]+amount>10000?'disabled':'')+'>+'+amount+'</button>').join('')+'</div>').join('')+'</div><button id="zagWithdraw" '+(busy||!sum(z.investment)?'disabled':'')+'>SACAR INVESTIMENTO</button></details></div>'+
 '<details class="zag-rules"><summary>CASAS E REGRAS</summary><p>1 passe gira a roleta: oito setores com 12,5% de chance cada. Receba de 2 a 6 dados, às vezes com cristais. Role até três dados da reserva; cada face tem chance igual. Escolha um dado e uma rota. Os outros dados ficam guardados.</p><p>Somente a casa de destino dá o efeito. Cofres são a exceção: cruzá-los guarda a mochila e rende 5% do investimento. A rota ousada tem selos exclusivos e tesouros ×3. Selos cobram 10% da mochila; desabamentos, 25%; auditorias, 10% do investimento. Três selos diferentes dão uma engrenagem para melhorar este tabuleiro. Repetidos dão dois fragmentos. A Oficina entrega fragmentos e proteção. Escudo bloqueia um perigo.</p><p>O Ímã troca o destino por uma casa de bônus duas posições à frente. Não troca cofres; termine a troca atual antes de usar outro. O Salto soma duas casas. O Inversor vira a face do dado.</p><p>Caminho, mão, ferramentas e investimentos ficam salvos. Sair durante uma animação conclui o resultado já sorteado. O tabuleiro continua sem limite de camadas. Cada passe libera no máximo dois dados extras; depois, casas de dado dão um fragmento. AFK compara os destinos visíveis e usa ajustes gratuitos. Não compra melhorias, não investe e não gasta ferramentas. Para ao fechar ou acabar os dados e passes.</p></details></section>';
}
function collectionMarkup(s){const z=s.zag;return '<div class="zag-collection"><strong>TRÊS SELOS → ⚙</strong><div>'+ZAG_SIGILS.map((name,i)=>'<span class="'+(z.sigils.includes(i)?'owned':'')+'"><b>'+['☀','☽','❧'][i]+'</b>'+name+'</span>').join('')+'</div><small>NA ROTA OUSADA · '+z.gears+' ENGRENAGENS</small></div>';}
export class ZagGame{
 constructor({state,music,onSave,onUpdate,open,close,soft}){Object.assign(this,{state,music,onSave,onUpdate,openDialog:open,closeDialog:close,soft});this.automatic=false;this.autoTimer=null;this.readyAt=0;this.selected=0;this.lastStep=-1;}
 open(){if(this.state.run)return;settleZag(this.state,Date.now(),true);this.onSave();this.render();}
 render(){
  const panels=[...document.querySelectorAll('.zag-workshops details')].map(d=>d.open),oldRoot=document.getElementById('zagGame'),oldWindow=oldRoot?.querySelector('.zag-board-window'),oldPawn=oldRoot?.querySelector('#zagPawn'),oldBase=Number(oldRoot?.querySelector('#zagBoardWorld')?.dataset.base),z=this.state.zag;
  const oldScroll=oldWindow?.scrollTop||0,oldHeight=oldWindow?.clientHeight||0,oldRelative=oldPawn&&oldWindow?oldPawn.getBoundingClientRect().top-oldWindow.getBoundingClientRect().top:null;
  const biome=zagTile(this.state.seed,z.position).biome,key=JSON.stringify([z.swap,z.guard,z.luck,z.bonusDice,z.modules]);
  const keep=!!oldWindow&&z.position>=oldBase&&z.position<=oldBase+6&&biome===this.boardBiome&&key===this.boardKey;
  const base=oldWindow?(keep?oldBase:z.position>=oldBase&&z.position<=oldBase+6?oldBase:zagBoardBase(z.position)):z.position;
  this.selected=Math.min(this.selected,Math.max(0,z.hand.length-1));this.openDialog(zagMarkup(this.state,this.selected,this.automatic,keep?'<div id="zagBoardSlot"></div>':null,base));const root=document.getElementById('zagGame');
  if(keep){root.querySelector('#zagBoardSlot').replaceWith(oldRoot.querySelector('.zag-board-head'),oldRoot.querySelector('.zag-lane-labels'),oldWindow);oldWindow.scrollTop=oldScroll;}
  this.wheel=root.querySelector('#zagWheel');this.pawn=root.querySelector('#zagPawn');this.hop=root.querySelector('#zagPawnHop');this.board=root.querySelector('#zagBoardWorld');this.base=Number(this.board.dataset.base);this.window=root.querySelector('.zag-board-window');
  this.headline=root.querySelector('#zagHeadline');this.detail=root.querySelector('#zagDetail');this.positionLabel=root.querySelector('#zagPosition');this.lastStep=-1;this.lastTick=-1;this.boardBiome=biome;this.boardKey=key;root.querySelectorAll('.zag-workshops details').forEach((d,i)=>d.open=!!panels[i]);
  if(!z.active||z.active.type!=='move')this.pawn.setAttribute('transform','translate('+Object.values(boardPoint(z.position,this.base,z.lastRoute)).join(',')+')');
  this.positionLabel.textContent='CASA '+fmt(z.position);root.querySelector('.zag-board-head span').textContent='CAMADA '+fmt(Math.floor(z.position/12)+1)+' · '+ZAG_BIOMES[biome];
  if(oldWindow){const nowRelative=this.pawn.getBoundingClientRect().top-this.window.getBoundingClientRect().top,target=oldRelative>=0&&oldRelative<=oldHeight?oldRelative:this.window.clientHeight*.44;this.window.scrollTop+=(nowRelative-target);}
  const mutate=(fn,sound='ui',notice='')=>{this.stopAuto();if(Date.now()<this.readyAt)return;const previous=this.state.zag.result;if(fn()){this.onSave();this.onUpdate();this.render();const result=this.state.zag.result;if(result&&result!==previous)this.celebrate(result);else{if(notice){this.headline.textContent=notice;this.detail.textContent='';}this.music.sfx(sound);}}else{this.headline.textContent='NÃO DÁ NESTA CASA';this.detail.textContent='Sem bônus disponível para o Ímã.';}};
  root.querySelector('#zagAuto').onclick=()=>{if(this.automatic)this.stopAuto();else{this.automatic=true;this.readyAt=Math.max(this.readyAt,Date.now()+600);this.autoTimer=setInterval(()=>this.frame(),500);}this.render();};
  root.querySelector('#zagKit').onclick=()=>mutate(()=>redeemZagGear(this.state),'claim','KIT DE FERRAMENTAS!');
  root.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>mutate(()=>upgradeZagModule(this.state,b.dataset.module),'claim','MÓDULO MELHORADO'));
  root.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>mutate(()=>adjustZagDie(this.state,this.selected,Number(b.dataset.adjust)),'zagTick'));
  root.querySelector('#zagSpin').onclick=()=>mutate(()=>spinZag(this.state),'zagStart');
  root.querySelector('#zagDeal')?.addEventListener('click',()=>mutate(()=>dealZag(this.state),'zagTick'));
  root.querySelector('#zagMove').onclick=()=>mutate(()=>moveZag(this.state,this.selected),'zagTick');
  root.querySelectorAll('button[data-route]').forEach(b=>b.onclick=()=>mutate(()=>chooseZagRoute(this.state,b.dataset.route)));
  root.querySelectorAll('[data-die]').forEach(b=>b.onclick=()=>{this.stopAuto();this.selected=Number(b.dataset.die);this.render();this.previewDestination();this.music.sfx('ui');});
  root.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>mutate(()=>useZagTool(this.state,b.dataset.tool,this.selected),'shield',ZAG_TOOLS[b.dataset.tool].name+' USADO'));
  root.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>mutate(()=>craftZagTool(this.state,b.dataset.craft),'claim','CARGA CRIADA'));
  root.querySelectorAll('[data-invest]').forEach(b=>b.onclick=()=>mutate(()=>investZag(this.state,...b.dataset.invest.split(':').map(Number)),'claim'));
  root.querySelector('#zagWithdraw').onclick=()=>mutate(()=>withdrawZag(this.state),'claim');
  root.querySelector('#zagBank').onclick=()=>mutate(()=>bankZag(this.state),'claim');
  const dest=zagDestination(this.state,this.selected);if(dest)root.querySelectorAll('[data-position="'+dest.position+'"]').forEach(g=>{if(g.dataset.route===this.state.zag.route||dest.position%12===0)g.classList.add('zag-destination');});
 }
 boardRatio(){return this.window.querySelector('.zag-board').getBoundingClientRect().width/600;}
 previewDestination(){const d=zagDestination(this.state,this.selected);if(!d)return;this.window.scrollTo({top:Math.max(0,((d.position-this.base)*108-50)*this.boardRatio()),behavior:this.soft?.()?'auto':'smooth'});}
 celebrate(result){
  const root=document.getElementById('zagGame');if(!root)return;
  const reward=zagRewardDisplay(result),feedback=root.querySelector('.zag-feedback'),map=root.querySelector('.zag-map');
  feedback.dataset.reward=reward.tone;
  const chips=document.createElement('div');chips.className='zag-reward-chips';chips.setAttribute('aria-hidden','true');
  chips.innerHTML=reward.tokens.map(t=>'<span class="zag-reward-chip" data-kind="'+t.kind+'" style="--reward-color:'+t.color+'">'+t.icon+'<b>'+t.text+'</b><small>'+t.label+'</small></span>').join('');
  feedback.append(chips);
  const focus=reward.tokens.find(t=>t.kind==='gain')||reward.tokens[0];
  const burst=document.createElement('div');burst.className='zag-reward-burst';burst.dataset.reward=reward.tone;burst.setAttribute('aria-hidden','true');
  burst.style.setProperty('--reward-color',focus?.color||P.lemon);
  burst.innerHTML='<div class="zag-reward-icon">'+(focus?.icon||art('crate'))+'</div><strong>'+reward.hero+'</strong><div class="zag-reward-rays">'+Array.from({length:8},(_,i)=>'<i style="--ray:'+i+'"></i>').join('')+'</div>';
  map.append(burst);
  const tile=root.querySelector('.zag-tile[data-position="'+result.position+'"][data-route="'+this.state.zag.lastRoute+'"]');if(tile)tile.classList.add('zag-reward-tile');
  this.music.zagReward?.(result,performance.now()/1000);
  setTimeout(()=>{burst.remove();tile?.classList.remove('zag-reward-tile');},1600);
 }
 finish(immediate=false){
  const action=this.state.zag.active,result=settleZag(this.state,Date.now(),immediate);if(!result)return false;
  this.onSave();this.onUpdate();if(document.getElementById('zagGame')){this.render();if(action?.type==='spin')this.wheel.style.transform='rotate('+(1440-22.5-action.prize*45)+'deg)';this.celebrate(result);}this.readyAt=Date.now()+550;return true;
 }
 stopAuto(){this.automatic=false;if(this.autoTimer!==null)clearInterval(this.autoTimer);this.autoTimer=null;const button=document.getElementById('zagAuto');if(button){button.setAttribute('aria-pressed','false');button.innerHTML='JOGAR AFK<small>USA DADOS E PASSES</small>';}}
 leave(){this.stopAuto();if(this.state.zag.active)this.finish(true);}
 frame(){
  if(!document.getElementById('zagGame')){this.stopAuto();return;}const r=zagRoundState(this.state);if(!r){if(this.automatic&&Date.now()>=this.readyAt){const plan=planZagTurn(this.state),previous=this.state.zag.result;if(!plan||!autoZagStep(this.state)){this.stopAuto();this.render();this.headline.textContent='AFK CONCLUÍDO';this.detail.textContent='Dados usados. Recompensas guardadas.';return;}this.selected=plan.index||0;this.readyAt=Date.now()+900;this.onSave();this.onUpdate();this.render();if(this.state.zag.result&&this.state.zag.result!==previous)this.celebrate(this.state.zag.result);}return;}if(this.finish())return;
  const soft=this.soft?.()||globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  if(r.type==='spin'){
   this.headline.textContent='GIRANDO A ROLETA';this.detail.textContent='';
   const angle=1440-22.5-r.prize*45;this.wheel.style.transform='rotate('+(soft?(r.progress>.9?angle:0):angle*(1-(1-r.progress)**3))+'deg)';
   const tick=Math.floor(r.progress*12);if(tick!==this.lastTick){this.lastTick=tick;this.music.sfx('zagTick');}
  }else{
   const travel=Math.min(r.steps,Math.max(0,(r.age-350)/ZAG_STEP_MS)),step=Math.floor(travel),f=travel-step;
   const a=boardPoint(r.from+step,this.base,step===0?(r.fromRoute||this.state.zag.lastRoute):r.route),b=boardPoint(r.from+Math.min(r.steps,step+1),this.base,r.route),ease=f*f*(3-2*f),x=a.x+(b.x-a.x)*ease,y=a.y+(b.y-a.y)*ease;
   this.pawn.setAttribute('transform','translate('+x+','+y+')');this.hop.setAttribute('transform','translate(0,'+(soft?0:-Math.sin(f*Math.PI)*15)+')');
   const now=performance.now(),dt=Math.min(80,now-(this.lastCameraAt||now)),target=Math.max(0,y*this.boardRatio()-this.window.clientHeight*.44);this.lastCameraAt=now;this.window.scrollTop+=(target-this.window.scrollTop)*(soft?1:1-Math.exp(-dt/105));
   this.headline.textContent=r.steps+' CASAS · '+routeName(r.route);this.detail.textContent='';this.positionLabel.textContent='CASA '+fmt(r.from+step);
   if(step!==this.lastStep){this.lastStep=step;this.music.sfx('zagTick');}
  }
 }
}
